#include <iostream>
#include <csignal>
#include <atomic>
#include <mutex>
#include <thread>
#include <vector>
#include <unordered_map>
#include <cstring>
#include <functional>
#include <condition_variable>
#include <chrono>
#include <limits>

namespace blockchain {

struct Transaction {
    uint64_t sender;
    uint64_t receiver;
    uint64_t amount;
    uint64_t nonce;
};

class CircuitBreaker {
private:
    std::atomic<int> tripped_;
    std::atomic<int> failure_count_;
    std::atomic<int> threshold_;
    std::atomic<int> state_; // 0=closed, 1=open, 2=half-open

    std::atomic<int> pending_recovery_;
    std::atomic<uint64_t> recovery_balance_;
    std::atomic<uint64_t> recovery_target_;

public:
    CircuitBreaker() : tripped_(0), failure_count_(0), threshold_(3),
                       state_(0), pending_recovery_(0),
                       recovery_balance_(0), recovery_target_(0) {}

    void set_threshold(int t) { threshold_.store(t, std::memory_order_release); }
    int get_state() const { return state_.load(std::memory_order_acquire); }
    bool is_tripped() const { return tripped_.load(std::memory_order_acquire) != 0; }

    void record_failure() {
        int count = failure_count_.fetch_add(1, std::memory_order_acq_rel) + 1;
        if (count >= threshold_.load(std::memory_order_acquire)) {
            trip();
        }
    }

    void trip() {
        tripped_.store(1, std::memory_order_release);
        state_.store(1, std::memory_order_release);
        pending_recovery_.store(1, std::memory_order_release);
    }

    void begin_recovery(uint64_t balance, uint64_t target) {
        recovery_balance_.store(balance, std::memory_order_release);
        recovery_target_.store(target, std::memory_order_release);
    }

    bool finalize_recovery() {
        if (pending_recovery_.load(std::memory_order_acquire)) {
            if (recovery_balance_.load(std::memory_order_acquire) >= 
                recovery_target_.load(std::memory_order_acquire)) {
                state_.store(2, std::memory_order_release);
                pending_recovery_.store(0, std::memory_order_release);
                return true;
            }
        }
        return false;
    }

    void reset() {
        failure_count_.store(0, std::memory_order_release);
        tripped_.store(0, std::memory_order_release);
        state_.store(0, std::memory_order_release);
        pending_recovery_.store(0, std::memory_order_release);
        recovery_balance_.store(0, std::memory_order_release);
        recovery_target_.store(0, std::memory_order_release);
    }
};

class SmartContract {
private:
    std::unordered_map<uint64_t, uint64_t> balances_;
    std::mutex state_mutex_;
    CircuitBreaker breaker_;
    std::vector<Transaction> pending_queue_;
    std::atomic<int> processing_;
    std::atomic<int> recovery_requested_;
    std::condition_variable recovery_cv_;
    std::mutex recovery_mutex_;
    std::thread recovery_thread_;
    std::atomic<bool> shutdown_;

    static SmartContract* instance_;

    // Internal transfer - assumes lock is held
    bool do_transfer(const Transaction& tx) {
        if (balances_[tx.sender] < tx.amount) {
            breaker_.record_failure();
            return false;
        }
        // Guard against integer overflow when crediting the receiver.
        uint64_t recv_balance = balances_[tx.receiver];
        if (recv_balance > std::numeric_limits<uint64_t>::max() - tx.amount) {
            breaker_.record_failure();
            return false;
        }
        balances_[tx.sender] -= tx.amount;
        balances_[tx.receiver] = recv_balance + tx.amount;
        return true;
    }

    void recovery_worker() {
        while (!shutdown_.load(std::memory_order_acquire)) {
            std::unique_lock<std::mutex> rlock(recovery_mutex_);
            recovery_cv_.wait(rlock, [this]() {
                return recovery_requested_.load(std::memory_order_acquire) != 0 ||
                       shutdown_.load(std::memory_order_acquire);
            });

            if (shutdown_.load(std::memory_order_acquire)) break;
            recovery_requested_.store(0, std::memory_order_release);
            rlock.unlock();

            // Perform recovery under proper lock
            std::lock_guard<std::mutex> lock(state_mutex_);
            if (breaker_.is_tripped()) {
                uint64_t contract_balance = 0;
                for (auto& pair : balances_) {
                    contract_balance += pair.second;
                }

                breaker_.begin_recovery(contract_balance, 1000);

                if (breaker_.finalize_recovery()) {
                    processing_.store(1, std::memory_order_release);
                    for (size_t i = 0; i < pending_queue_.size(); i++) {
                        do_transfer(pending_queue_[i]);
                    }
                    pending_queue_.clear();
                    processing_.store(0, std::memory_order_release);
                    breaker_.reset();
                }
            }
        }
    }

public:
    SmartContract() : processing_(0), recovery_requested_(0), shutdown_(false) {
        instance_ = this;
        recovery_thread_ = std::thread(&SmartContract::recovery_worker, this);
    }

    ~SmartContract() {
        shutdown_.store(true, std::memory_order_release);
        recovery_cv_.notify_one();
        if (recovery_thread_.joinable()) recovery_thread_.join();
    }

    static SmartContract* get_instance() { return instance_; }

    void initialize(uint64_t addr, uint64_t balance) {
        std::lock_guard<std::mutex> lock(state_mutex_);
        balances_[addr] = balance;
    }

    uint64_t get_balance(uint64_t addr) {
        std::lock_guard<std::mutex> lock(state_mutex_);
        return balances_[addr];
    }

    bool submit_transaction(const Transaction& tx) {
        std::lock_guard<std::mutex> lock(state_mutex_);

        if (breaker_.get_state() == 1) {
            pending_queue_.push_back(tx);
            return false;
        }

        processing_.store(1, std::memory_order_release);
        bool result = do_transfer(tx);
        processing_.store(0, std::memory_order_release);
        return result;
    }

    // Signal handler only sets a flag - all work done in dedicated thread
    static void signal_recovery_handler(int sig) {
        SmartContract* self = instance_;
        if (!self) return;
        // Only set atomic flag - async-signal-safe
        self->recovery_requested_.store(1, std::memory_order_release);
        // Note: cannot call notify from signal handler safely,
        // but the recovery thread polls periodically via timed wait
    }

    void install_recovery_handler() {
        struct sigaction sa;
        memset(&sa, 0, sizeof(sa));
        sa.sa_handler = signal_recovery_handler;
        sigemptyset(&sa.sa_mask);
        sa.sa_flags = SA_RESTART;
        sigaction(SIGUSR1, &sa, nullptr);
    }

    void trigger_recovery() {
        recovery_requested_.store(1, std::memory_order_release);
        recovery_cv_.notify_one();
    }

    size_t pending_count() {
        std::lock_guard<std::mutex> lock(state_mutex_);
        return pending_queue_.size();
    }
};

SmartContract* SmartContract::instance_ = nullptr;

} // namespace blockchain

int main() {
    blockchain::SmartContract contract;
    contract.install_recovery_handler();

    contract.initialize(1, 10000);
    contract.initialize(2, 5000);
    contract.initialize(3, 0);

    // Normal operations
    blockchain::Transaction tx1{1, 3, 500, 1};
    contract.submit_transaction(tx1);

    // Force circuit breaker trip
    for (int i = 0; i < 5; i++) {
        blockchain::Transaction bad_tx{3, 1, 99999, (uint64_t)i};
        contract.submit_transaction(bad_tx);
    }

    // This should be queued
    blockchain::Transaction tx2{1, 2, 200, 2};
    contract.submit_transaction(tx2);

    std::cout << "Pending: " << contract.pending_count() << std::endl;
    std::cout << "Balance[1]: " << contract.get_balance(1) << std::endl;

    // Recovery is safe - done in dedicated thread with proper locking
    std::thread worker([&]() {
        for (int i = 0; i < 100; i++) {
            blockchain::Transaction tx{1, 2, 1, (uint64_t)(100+i)};
            contract.submit_transaction(tx);
        }
    });

    std::this_thread::sleep_for(std::chrono::milliseconds(1));
    contract.trigger_recovery();

    worker.join();

    // Give recovery thread time to process
    std::this_thread::sleep_for(std::chrono::milliseconds(50));

    std::cout << "Final Balance[1]: " << contract.get_balance(1) << std::endl;
    std::cout << "Final Balance[2]: " << contract.get_balance(2) << std::endl;
    return 0;
}
